toolArgs.file_text:
@page "/book-appointment"
@rendermode InteractiveServer
@using sv_9eda9e5314e24b6f9d09fdd07488650f.Models
@using sv_9eda9e5314e24b6f9d09fdd07488650f.Services
@inject AppointmentService AppointmentService

<PageTitle>Book Appointment</PageTitle>

<h3>Book an Appointment</h3>

<EditForm EditContext="editContext" OnValidSubmit="HandleSubmit">
    <DataAnnotationsValidator />
    <CustomValidator @ref="customValidator" />

    @* ── STEP 1 ── *@
    <fieldset>
        <legend>Patient Information</legend>

        <div class="mb-3">
            <label class="form-label" for="patientName">Patient Name</label>
            <InputText id="patientName" class="form-control" @bind-Value="model.PatientName" />
            <ValidationMessage For="() => model.PatientName" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="email">Email</label>
            <InputText id="email" class="form-control" @bind-Value="model.Email" />
            <ValidationMessage For="() => model.Email" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="phone">Phone</label>
            <InputText id="phone" class="form-control" @bind-Value="model.Phone" />
            <ValidationMessage For="() => model.Phone" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="insurance">Insurance Provider</label>
            <InputSelect id="insurance" class="form-select" @bind-Value="model.InsuranceProvider">
                <option value="">-- Select --</option>
                <option value="Aetna">Aetna</option>
                <option value="BlueCross">BlueCross</option>
                <option value="Cigna">Cigna</option>
                <option value="UnitedHealth">UnitedHealth</option>
                <option value="None">None</option>
            </InputSelect>
            <ValidationMessage For="() => model.InsuranceProvider" />
        </div>
    </fieldset>

    @if (!showStep2)
    {
        <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">
            Next
        </button>
    }

    @* ── STEP 2 ── *@
    @if (showStep2)
    {
        <fieldset class="mt-4">
            <legend>Appointment Details</legend>

            <div class="mb-3">
                <label class="form-label" for="doctor">Preferred Doctor</label>
                <InputSelect id="doctor" class="form-select" @bind-Value="model.Doctor"
                             @bind-Value:after="OnDoctorChanged">
                    <option value="">-- Select --</option>
                    @foreach (var doc in doctors)
                    {
                        <option value="@doc">@doc</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => model.Doctor" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="date">Date</label>
                <InputDate id="date" class="form-control" @bind-Value="model.Date"
                           @bind-Value:after="OnDateChanged" />
                <ValidationMessage For="() => model.Date" />
                @if (model.Date.HasValue && model.Date.Value <= DateOnly.FromDateTime(DateTime.Today))
                {
                    <div class="text-danger">Date must be in the future.</div>
                }
            </div>

            <div class="mb-3">
                <label class="form-label" for="timeSlot">Time Slot</label>
                <InputSelect id="timeSlot" class="form-select" @bind-Value="model.TimeSlot">
                    <option value="">-- Select --</option>
                    @foreach (var slot in availableSlots)
                    {
                        <option value="@slot">@slot</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => model.TimeSlot" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="reason">Reason for Visit</label>
                <InputTextArea id="reason" class="form-control" @bind-Value="model.ReasonForVisit" rows="3" />
                <ValidationMessage For="() => model.ReasonForVisit" />
                <small class="text-muted">@((model.ReasonForVisit?.Length ?? 0))/500</small>
            </div>

            <button type="button" class="btn btn-secondary me-2" @onclick="BackToStep1">
                Back
            </button>
            <button type="button" class="btn btn-info me-2" disabled="@isSubmitting"
                    @onclick="CheckAvailability">
                @(isSubmitting ? "Checking..." : "Check Availability")
            </button>
            <button type="submit" class="btn btn-success" disabled="@(!availabilityChecked || isSubmitting)">
                Confirm Appointment
            </button>
        </fieldset>
    }

    @if (submitted)
    {
        <div class="alert alert-success mt-3">
            Appointment booked successfully!
        </div>
    }
</EditForm>

@code {
    private AppointmentModel model = new();
    private EditContext editContext = default!;
    private CustomValidator? customValidator;

    private bool showStep2;
    private bool isSubmitting;
    private bool submitted;
    private bool availabilityChecked;

    private List<string> doctors = [];
    private List<string> availableSlots = [];

    protected override async Task OnInitializedAsync()
    {
        editContext = new EditContext(model);
        doctors = await AppointmentService.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        // Validate only Step 1 fields
        var step1Valid =
            !string.IsNullOrWhiteSpace(model.PatientName) &&
            !string.IsNullOrWhiteSpace(model.Email) &&
            new System.ComponentModel.DataAnnotations.EmailAddressAttribute().IsValid(model.Email) &&
            !string.IsNullOrWhiteSpace(model.Phone) &&
            !string.IsNullOrWhiteSpace(model.InsuranceProvider);

        // Trigger validation UI for step 1 fields
        editContext.NotifyFieldChanged(editContext.Field(nameof(model.PatientName)));
        editContext.NotifyFieldChanged(editContext.Field(nameof(model.Email)));
        editContext.NotifyFieldChanged(editContext.Field(nameof(model.Phone)));
        editContext.NotifyFieldChanged(editContext.Field(nameof(model.InsuranceProvider)));

        if (step1Valid)
        {
            showStep2 = true;
            availabilityChecked = false;
        }
    }

    private async Task OnDoctorChanged()
    {
        availableSlots = [];
        model.TimeSlot = null;
        availabilityChecked = false;

        if (!string.IsNullOrEmpty(model.Doctor) && model.Date.HasValue)
        {
            availableSlots = await AppointmentService.GetAvailableSlotsAsync(model.Doctor, model.Date.Value);
        }
    }

    private async Task OnDateChanged()
    {
        availableSlots = [];
        model.TimeSlot = null;
        availabilityChecked = false;

        if (!string.IsNullOrEmpty(model.Doctor) && model.Date.HasValue)
        {
            availableSlots = await AppointmentService.GetAvailableSlotsAsync(model.Doctor, model.Date.Value);
        }
    }

    private async Task CheckAvailability()
    {
        customValidator?.ClearErrors();
        availabilityChecked = false;

        // Client-side: date must be in the future
        if (model.Date.HasValue && model.Date.Value <= DateOnly.FromDateTime(DateTime.Today))
        {
            customValidator?.DisplayErrors(new Dictionary<string, List<string>>
            {
                ["Date"] = ["Date must be in the future."]
            });
            return;
        }

        isSubmitting = true;
        try
        {
            var errors = await AppointmentService.ValidatePatientAsync(
                model.Email, model.InsuranceProvider, model.Doctor, model.TimeSlot);

            if (errors.Count > 0)
            {
                customValidator?.DisplayErrors(errors);
            }
            else
            {
                availabilityChecked = true;
            }
        }
        finally
        {
            isSubmitting = false;
        }
    }

    private void BackToStep1()
    {
        showStep2 = false;
        availabilityChecked = false;
    }

    private async Task HandleSubmit()
    {
        if (!availabilityChecked)
            return;

        // Future-date check
        if (model.Date.HasValue && model.Date.Value <= DateOnly.FromDateTime(DateTime.Today))
            return;

        isSubmitting = true;
        try
        {
            // Final server validation
            var errors = await AppointmentService.ValidatePatientAsync(
                model.Email, model.InsuranceProvider, model.Doctor, model.TimeSlot);

            if (errors.Count > 0)
            {
                customValidator?.DisplayErrors(errors);
                availabilityChecked = false;
                return;
            }

            submitted = true;
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

